import hashlib, json, sys
from pathlib import Path

target = Path(sys.argv[1])
expected = {
    p.relative_to(Path("schemas")).as_posix(): p.read_bytes()
    for p in Path("schemas").rglob("*.json")
}
actual = {p.relative_to(target).as_posix(): p.read_bytes() for p in target.rglob("*.json")}
equal = len(expected) == 10 and expected == actual
print(
    json.dumps(
        {
            "schema_version": 1,
            "expected_file_count": len(expected),
            "actual_file_count": len(actual),
            "same_file_set_and_bytes": equal,
            "expected_sha256": {k: hashlib.sha256(v).hexdigest() for k, v in expected.items()},
            "actual_sha256": {k: hashlib.sha256(v).hexdigest() for k, v in actual.items()},
        },
        sort_keys=True,
    )
)
raise SystemExit(0 if equal else 1)
